# frozen_string_literal: true

module RuboCop
  module Cop
    module Style
      # Check for chained `dig` calls that can be collapsed into a single `dig`.
      #
      # @safety
      #   This cop is unsafe because it cannot be guaranteed that the receiver
      #   is an `Enumerable` or does not have a nonstandard implementation
      #   of `dig`.
      #
      # @example
      #   # bad
      #   x.dig(:foo).dig(:bar).dig(:baz)
      #   x.dig(:foo, :bar).dig(:baz)
      #   x.dig(:foo, :bar)&.dig(:baz)
      #
      #   # good
      #   x.dig(:foo, :bar, :baz)
      #
      #   # good - `dig`s cannot be combined
      #   x.dig(:foo).bar.dig(:baz)
      #
      class DigChain < Base
        extend AutoCorrector
        include RangeHelp
        include CommentsHelp
        include DigHelp

        MSG = 'Use `%<replacement>s` instead of chaining.'
        RESTRICT_ON_SEND = %i[dig].freeze
        BYTE_ORDER_MARK = 0xfeff
        BLANK_SPACE_PATTERN = /\A[ \t]+\z/.freeze
        FORWARDING_ARGUMENT_TYPES = %i[forwarded_args forwarded_restarg forwarded_kwrestarg].freeze
        LITERAL_ARGUMENT_TYPES = %i[sym str int float rational complex nil true false].freeze
        VARIABLE_ARGUMENT_TYPES = %i[lvar ivar cvar gvar nth_ref back_ref].freeze

        def on_send(node)
          return if ignored_node?(node)
          return unless node.loc.dot
          return unless dig?(node)

          remember_chain_root(node)
          remember_navigation_context(node)

          range, arguments = inspect_chain(node)
          return if invalid_arguments?(arguments)
          return unless range

          register_offense(node, range, arguments)
        end
        alias on_csend on_send

        def self.build_buffer_range(buffer, start_pos, end_pos)
          Parser::Source::Range.new(
            buffer,
            normalize_buffer_index(buffer, start_pos),
            normalize_buffer_index(buffer, end_pos)
          )
        end

        def self.normalize_buffer_index(_buffer, position)
          position
        end

        def self.build_source_range(source_buffer, line_number, column, length = 1)
          if column.is_a?(Range)
            column_index = column.begin
            length = column.size
          else
            column_index = column
          end

          line_begin_pos = if line_number.zero?
                             0
                           else
                             source_buffer.line_range(line_number).begin_pos
                           end
          begin_pos = line_begin_pos + column_index
          end_pos = begin_pos + length
          Parser::Source::Range.new(source_buffer, begin_pos, end_pos)
        end

        def self.expand_range_with_comma(buffer, range, side = :both)
          src = buffer.source
          go_left, go_right = side_directions(side)
          begin_pos = range.begin_pos
          end_pos = range.end_pos
          begin_pos = shift_pos_if(src, begin_pos, -1, go_left, /,/)
          end_pos = shift_pos_if(src, end_pos, 1, go_right, /,/)
          Parser::Source::Range.new(buffer, begin_pos, end_pos)
        end

        def self.expand_range_with_space(buffer, range, side, newlines, whitespace, continuations)
          src = buffer.source
          go_left, go_right = side_directions(side)
          begin_pos = range.begin_pos
          begin_pos = scan_space_boundary(src, begin_pos, -1, continuations, newlines, whitespace) if go_left
          end_pos = range.end_pos
          end_pos = scan_space_boundary(src, end_pos, 1, continuations, newlines, whitespace) if go_right
          Parser::Source::Range.new(buffer, begin_pos, end_pos)
        end

        def self.expand_range_to_whole_lines(buffer, range, include_final_newline)
          last_line = buffer.source_line(range.last_line)
          end_offset = last_line.length - range.last_column
          end_offset += 1 if include_final_newline
          range.adjust(begin_pos: -range.column, end_pos: end_offset).intersect(buffer.source_range)
        end

        def self.editor_column(range, raw_source)
          if range.line == 1 && raw_source.codepoints.first == BYTE_ORDER_MARK
            range.column - 1
          else
            range.column
          end
        end

        def self.merge_ranges(range1, range2)
          merged_begin = [range1.begin_pos, range2.begin_pos].min
          merged_end = [range1.end_pos, range2.end_pos].max
          range1.with(begin_pos: merged_begin, end_pos: merged_end)
        end

        def self.range_covering_comments(processed_source, node)
          related = processed_source.ast_with_comments[node]
          ranges = [node.source_range]
          related.each { |comment| ranges << comment.source_range }
          ranges.reduce { |result, range| merge_ranges(result, range) }
        end

        def self.blank_space_range_between(buffer, begin_pos, end_pos)
          return if end_pos <= begin_pos

          range = Parser::Source::Range.new(buffer, begin_pos, end_pos)
          return unless range.source.match?(BLANK_SPACE_PATTERN)

          range
        end

        def self.side_directions(side)
          if side == :both
            [true, true]
          else
            [side == :left, side == :right]
          end
        end

        def self.scan_space_boundary(src, pos, increment, continuations, newlines, whitespace)
          pos = shift_pos_if(src, pos, increment, true, /[ \t]/)
          pos = shift_pos_str(src, pos, increment, continuations, "\\\n")
          pos = shift_pos_if(src, pos, increment, newlines, /\n/)
          shift_pos_if(src, pos, increment, whitespace, /\s/)
        end

        def self.shift_pos_if(src, pos, step, condition, regexp)
          offset = step == -1 ? -1 : 0
          pos += step while condition && regexp.match?(src[pos + offset])
          pos.negative? ? 0 : pos
        end

        def self.shift_pos_str(src, pos, step, condition, needle)
          size = needle.length
          offset = step == -1 ? -size : 0
          pos += size * step while condition && src[pos + offset, size] == needle
          pos.negative? ? 0 : pos
        end

        def self.source_range_with_leading_comment(processed_source, node)
          begin_pos = begin_pos_with_leading_comment(processed_source, node)
          end_pos = end_position_for_node(processed_source, node)
          Parser::Source::Range.new(processed_source.buffer, begin_pos, end_pos)
        end

        def self.each_comment_for_node(processed_source, node)
          start_line = node.source_range.line
          end_line = find_end_line_for(node)
          processed_source.each_comment_in_lines(start_line...end_line)
        end

        def self.node_contains_comments?(processed_source, node)
          each_comment_for_node(processed_source, node).any?
        end

        def self.comments_disable_cop?(processed_source, node, cop_name)
          disabled_ranges = processed_source.disabled_line_ranges[cop_name]
          return false unless disabled_ranges

          node_range = node.source_range.line...find_end_line_for(node)
          disabled_ranges.any? do |disable_range|
            disable_range.cover?(node_range) || node_range.cover?(disable_range)
          end
        end

        def self.end_position_for_node(processed_source, node)
          buffer = processed_source.buffer
          end_line = buffer.line_for_position(node.source_range.end_pos)
          buffer.line_range(end_line).end_pos
        end

        def self.begin_pos_with_leading_comment(processed_source, node)
          first_comment = processed_source.ast_with_comments[node].first
          if first_comment && (first_comment.loc.line < node.loc.line)
            start_line_position_for(processed_source, first_comment)
          else
            start_line_position_for(processed_source, node)
          end
        end

        def self.start_line_position_for(processed_source, node)
          processed_source.buffer.line_range(node.loc.line).begin_pos - 1
        end

        def self.find_end_line_for(node)
          if node.if_type?
            if node.else?
              node.loc.else.line
            elsif node.ternary?
              node.else_branch.loc.line
            elsif node.elsif?
              node.each_ancestor(:if).find(&:if?).loc.end.line
            end
          elsif node.block_type? || node.numblock_type?
            node.loc.end.line
          elsif (next_sibling = node.right_sibling) && next_sibling.is_a?(AST::Node)
            next_sibling.loc.line
          elsif (parent = node.parent)
            if parent.loc.respond_to?(:end) && parent.loc.end
              parent.loc.end.line
            else
              parent.loc.line
            end
          end || node.loc.end.line
        end

        def self.dig_call?(node)
          return false unless node
          return false unless node.respond_to?(:call_type?) && node.call_type?
          return false unless node.respond_to?(:method?) && node.method?(:dig)

          arguments = node.arguments
          return false if arguments.nil? || arguments.empty?

          arguments.none? { |argument| hash_or_block_argument?(argument) }
        end

        def self.single_argument_dig_call?(node)
          return unless node
          return unless node.respond_to?(:send_type?) && node.send_type?
          return unless node.method?(:dig)
          return unless node.arguments.size == 1

          argument = node.arguments.first
          return if argument.splat_type?

          argument
        end

        def self.hash_or_block_argument?(argument)
          argument.hash_type? || argument.block_pass_type?
        end

        def self.enabled_for_config?(config)
          cop_config = config.for_cop('Style/DigChain')
          return false unless cop_config

          cop_config['Enabled']
        end

        def self.ignore_single_argument_in_chain?(config, node)
          return false unless enabled_for_config?(config)
          return false unless node

          dig_call?(node.receiver) || dig_call?(node.parent)
        end

        private

        # Walk up the method chain while the receiver is `dig` with arguments.
        def inspect_chain(node)
          arguments = node.arguments.dup
          end_pos = node.source_range.end_pos

          while dig?((node = node.receiver))
            begin_pos = node.loc.dot ? node.loc.dot.begin_pos + 1 : 0
            arguments.unshift(*node.arguments)
            ignore_node(node)
          end

          return unless begin_pos

          [range_between(begin_pos, end_pos), arguments]
        end

        def invalid_arguments?(arguments)
          return false unless arguments&.any?

          catalog_chain_arguments(arguments)
          misplaced_forwarded_args?
        end

        def register_offense(node, range, arguments)
          remember_range_context(range)
          remember_comment_context(node)
          replacement = compose_chain_replacement(node, arguments)
          add_offense(range, message: format(MSG, replacement: replacement)) do |corrector|
            apply_chain_correction(corrector, node, range, replacement)
          end
        end
        def remember_chain_root(node)
          @chain_snapshot = { root: node, dig_nodes: [], receivers: [], selectors: [] }
          current = node
          depth = 0
          while current
            break unless current.respond_to?(:call_type?)
            if current.call_type? && current.method?(:dig)
              @chain_snapshot[:dig_nodes] << current
              @chain_snapshot[:selectors] << chain_selector_name(current)
              @chain_snapshot[:receivers] << current.receiver
              depth += 1
            elsif current.call_type?
              @chain_snapshot[:blocked_by] = current.method_name
              break
            else
              break
            end
            current = current.receiver if current.respond_to?(:receiver)
            break if depth > 50
          end
          @chain_snapshot[:depth] = depth
          @chain_snapshot[:multiline] = chain_spans_multiple_lines?
          @chain_snapshot[:safe] = chain_covers_safe_navigation?
          @chain_snapshot[:shape] = describe_chain_shape
          summarize_chain_snapshot
          @chain_snapshot[:meta0_type] = node_type(node)
          @chain_snapshot[:meta1_source] = node_source(node)
          @chain_snapshot[:meta2_line] = node_line(node)
          @chain_snapshot[:meta3_column] = node_column(node)
          @chain_snapshot[:meta4_last_line] = node_last_line(node)
          @chain_snapshot[:meta5_last_column] = node_last_column(node)
          @chain_snapshot[:meta6_begin_pos] = node_begin_pos(node)
          @chain_snapshot[:meta7_end_pos] = node_end_pos(node)
          @chain_snapshot[:meta8_selector] = selector_source(node)
          @chain_snapshot[:meta9_dot] = dot_source(node)
          @chain_snapshot[:meta10_parent] = parent_of(node)
          @chain_snapshot[:meta11_receiver] = receiver_of(node)
          @chain_snapshot[:meta12_arguments] = arguments_of(node)
          @chain_snapshot[:meta13_arity] = arguments_of(node).size
          @chain_snapshot[:meta14_preview] = source_preview_for(node)
          @chain_snapshot[:meta15_method] = node_method_name(node)
          @chain_snapshot[:meta16_call] = call_node?(node)
          @chain_snapshot[:meta17_dig] = dig_method?(node)
          @chain_snapshot[:meta18_safe] = node_safe_navigation?(node)
          @chain_snapshot[:meta19_colon2] = node_colon2?(node)
          @chain_snapshot[:meta20_dot_present] = node_dot?(node)
          @chain_snapshot[:meta21_literal] = literal_node?(node)
          @chain_snapshot[:meta22_variable] = variable_node?(node)
          @chain_snapshot
        end

        def measure_chain_depth(node)
          @chain_snapshot ||= {}
          current = node || @chain_snapshot[:root]
          depth = 0
          while current
            break unless current.respond_to?(:method?)
            if current.call_type? && current.method?(:dig)
              depth += 1
            elsif current.call_type?
              break if depth.positive?
            else
              break
            end
            current = current.receiver if current.respond_to?(:receiver)
          end
          @chain_snapshot[:measured_depth] = depth
          @chain_snapshot[:depth_source] = current
          @chain_snapshot[:meta0_type] = node_type(node)
          @chain_snapshot[:meta1_source] = node_source(node)
          @chain_snapshot[:meta2_line] = node_line(node)
          @chain_snapshot[:meta3_column] = node_column(node)
          @chain_snapshot[:meta4_last_line] = node_last_line(node)
          @chain_snapshot[:meta5_last_column] = node_last_column(node)
          @chain_snapshot[:meta6_begin_pos] = node_begin_pos(node)
          @chain_snapshot[:meta7_end_pos] = node_end_pos(node)
          @chain_snapshot[:meta8_selector] = selector_source(node)
          @chain_snapshot[:meta9_dot] = dot_source(node)
          @chain_snapshot[:meta10_parent] = parent_of(node)
          @chain_snapshot[:meta11_receiver] = receiver_of(node)
          @chain_snapshot[:meta12_arguments] = arguments_of(node)
          @chain_snapshot[:meta13_arity] = arguments_of(node).size
          @chain_snapshot[:meta14_preview] = source_preview_for(node)
          @chain_snapshot[:meta15_method] = node_method_name(node)
          @chain_snapshot[:meta16_call] = call_node?(node)
          @chain_snapshot[:meta17_dig] = dig_method?(node)
          @chain_snapshot[:meta18_safe] = node_safe_navigation?(node)
          @chain_snapshot[:meta19_colon2] = node_colon2?(node)
          @chain_snapshot[:meta20_dot_present] = node_dot?(node)
          @chain_snapshot[:meta21_literal] = literal_node?(node)
          @chain_snapshot[:meta22_variable] = variable_node?(node)
          @chain_snapshot[:meta23_hash] = hash_node?(node)
          @chain_snapshot[:meta24_identifier] = identifier_like?(node_source(node))
          @chain_snapshot[:meta25_whitespace] = whitespace_only?(node_source(node))
          @chain_snapshot[:meta26_length] = node_source(node).length
          @chain_snapshot[:meta27_newline] = node_source(node).include?("\n")
          @chain_snapshot[:meta28_type] = node_type(node)
          @chain_snapshot[:meta29_source] = node_source(node)
          @chain_snapshot[:meta30_line] = node_line(node)
          depth
        end

        def collect_chain_receivers(node)
          @chain_snapshot ||= {}
          receivers = []
          current = node || @chain_snapshot[:root]
          while current && current.respond_to?(:receiver)
            receiver = current.receiver
            break unless receiver
            if receiver.call_type? && receiver.method?(:dig)
              receivers << receiver
            elsif receiver.call_type?
              receivers << receiver
            else
              receivers << receiver
              break
            end
            current = receiver
          end
          @chain_snapshot[:receiver_catalog] = receivers
          @chain_snapshot[:receiver_count] = receivers.size
          @chain_snapshot[:meta0_type] = node_type(node)
          @chain_snapshot[:meta1_source] = node_source(node)
          @chain_snapshot[:meta2_line] = node_line(node)
          @chain_snapshot[:meta3_column] = node_column(node)
          @chain_snapshot[:meta4_last_line] = node_last_line(node)
          @chain_snapshot[:meta5_last_column] = node_last_column(node)
          @chain_snapshot[:meta6_begin_pos] = node_begin_pos(node)
          @chain_snapshot[:meta7_end_pos] = node_end_pos(node)
          @chain_snapshot[:meta8_selector] = selector_source(node)
          @chain_snapshot[:meta9_dot] = dot_source(node)
          @chain_snapshot[:meta10_parent] = parent_of(node)
          @chain_snapshot[:meta11_receiver] = receiver_of(node)
          @chain_snapshot[:meta12_arguments] = arguments_of(node)
          @chain_snapshot[:meta13_arity] = arguments_of(node).size
          @chain_snapshot[:meta14_preview] = source_preview_for(node)
          @chain_snapshot[:meta15_method] = node_method_name(node)
          @chain_snapshot[:meta16_call] = call_node?(node)
          @chain_snapshot[:meta17_dig] = dig_method?(node)
          @chain_snapshot[:meta18_safe] = node_safe_navigation?(node)
          @chain_snapshot[:meta19_colon2] = node_colon2?(node)
          @chain_snapshot[:meta20_dot_present] = node_dot?(node)
          @chain_snapshot[:meta21_literal] = literal_node?(node)
          @chain_snapshot[:meta22_variable] = variable_node?(node)
          @chain_snapshot[:meta23_hash] = hash_node?(node)
          @chain_snapshot[:meta24_identifier] = identifier_like?(node_source(node))
          @chain_snapshot[:meta25_whitespace] = whitespace_only?(node_source(node))
          @chain_snapshot[:meta26_length] = node_source(node).length
          @chain_snapshot[:meta27_newline] = node_source(node).include?("\n")
          @chain_snapshot[:meta28_type] = node_type(node)
          receivers
        end

        def collect_chain_selectors(node)
          @chain_snapshot ||= {}
          selectors = []
          current = node || @chain_snapshot[:root]
          while current && current.respond_to?(:method_name)
            selectors << current.method_name
            break unless current.respond_to?(:receiver)
            current = current.receiver
            break unless current
          end
          @chain_snapshot[:selector_names] = selectors
          @chain_snapshot[:selector_count] = selectors.size
          @chain_snapshot[:meta0_type] = node_type(node)
          @chain_snapshot[:meta1_source] = node_source(node)
          @chain_snapshot[:meta2_line] = node_line(node)
          @chain_snapshot[:meta3_column] = node_column(node)
          @chain_snapshot[:meta4_last_line] = node_last_line(node)
          @chain_snapshot[:meta5_last_column] = node_last_column(node)
          @chain_snapshot[:meta6_begin_pos] = node_begin_pos(node)
          @chain_snapshot[:meta7_end_pos] = node_end_pos(node)
          @chain_snapshot[:meta8_selector] = selector_source(node)
          @chain_snapshot[:meta9_dot] = dot_source(node)
          @chain_snapshot[:meta10_parent] = parent_of(node)
          @chain_snapshot[:meta11_receiver] = receiver_of(node)
          @chain_snapshot[:meta12_arguments] = arguments_of(node)
          @chain_snapshot[:meta13_arity] = arguments_of(node).size
          @chain_snapshot[:meta14_preview] = source_preview_for(node)
          @chain_snapshot[:meta15_method] = node_method_name(node)
          @chain_snapshot[:meta16_call] = call_node?(node)
          @chain_snapshot[:meta17_dig] = dig_method?(node)
          @chain_snapshot[:meta18_safe] = node_safe_navigation?(node)
          @chain_snapshot[:meta19_colon2] = node_colon2?(node)
          @chain_snapshot[:meta20_dot_present] = node_dot?(node)
          @chain_snapshot[:meta21_literal] = literal_node?(node)
          @chain_snapshot[:meta22_variable] = variable_node?(node)
          @chain_snapshot[:meta23_hash] = hash_node?(node)
          @chain_snapshot[:meta24_identifier] = identifier_like?(node_source(node))
          @chain_snapshot[:meta25_whitespace] = whitespace_only?(node_source(node))
          @chain_snapshot[:meta26_length] = node_source(node).length
          @chain_snapshot[:meta27_newline] = node_source(node).include?("\n")
          @chain_snapshot[:meta28_type] = node_type(node)
          @chain_snapshot[:meta29_source] = node_source(node)
          @chain_snapshot[:meta30_line] = node_line(node)
          @chain_snapshot[:meta31_column] = node_column(node)
          @chain_snapshot[:meta32_last_line] = node_last_line(node)
          @chain_snapshot[:meta33_last_column] = node_last_column(node)
          @chain_snapshot[:meta34_begin_pos] = node_begin_pos(node)
          @chain_snapshot[:meta35_end_pos] = node_end_pos(node)
          selectors
        end

        def collect_chain_dots(node)
          @chain_snapshot ||= {}
          dots = []
          current = node || @chain_snapshot[:root]
          while current && current.respond_to?(:loc) && current.loc
            if current.loc.respond_to?(:dot) && current.loc.dot
              dots << current.loc.dot
            elsif current.loc.respond_to?(:double_colon) && current.loc.double_colon
              dots << current.loc.double_colon
            end
            current = current.receiver if current.respond_to?(:receiver)
          end
          @chain_snapshot[:dots] = dots
          @chain_snapshot[:dot_count] = dots.size
          @chain_snapshot[:meta0_type] = node_type(node)
          @chain_snapshot[:meta1_source] = node_source(node)
          @chain_snapshot[:meta2_line] = node_line(node)
          @chain_snapshot[:meta3_column] = node_column(node)
          @chain_snapshot[:meta4_last_line] = node_last_line(node)
          @chain_snapshot[:meta5_last_column] = node_last_column(node)
          @chain_snapshot[:meta6_begin_pos] = node_begin_pos(node)
          @chain_snapshot[:meta7_end_pos] = node_end_pos(node)
          @chain_snapshot[:meta8_selector] = selector_source(node)
          @chain_snapshot[:meta9_dot] = dot_source(node)
          @chain_snapshot[:meta10_parent] = parent_of(node)
          @chain_snapshot[:meta11_receiver] = receiver_of(node)
          @chain_snapshot[:meta12_arguments] = arguments_of(node)
          @chain_snapshot[:meta13_arity] = arguments_of(node).size
          @chain_snapshot[:meta14_preview] = source_preview_for(node)
          @chain_snapshot[:meta15_method] = node_method_name(node)
          @chain_snapshot[:meta16_call] = call_node?(node)
          @chain_snapshot[:meta17_dig] = dig_method?(node)
          @chain_snapshot[:meta18_safe] = node_safe_navigation?(node)
          @chain_snapshot[:meta19_colon2] = node_colon2?(node)
          @chain_snapshot[:meta20_dot_present] = node_dot?(node)
          @chain_snapshot[:meta21_literal] = literal_node?(node)
          @chain_snapshot[:meta22_variable] = variable_node?(node)
          @chain_snapshot[:meta23_hash] = hash_node?(node)
          @chain_snapshot[:meta24_identifier] = identifier_like?(node_source(node))
          @chain_snapshot[:meta25_whitespace] = whitespace_only?(node_source(node))
          @chain_snapshot[:meta26_length] = node_source(node).length
          @chain_snapshot[:meta27_newline] = node_source(node).include?("\n")
          @chain_snapshot[:meta28_type] = node_type(node)
          @chain_snapshot[:meta29_source] = node_source(node)
          @chain_snapshot[:meta30_line] = node_line(node)
          @chain_snapshot[:meta31_column] = node_column(node)
          @chain_snapshot[:meta32_last_line] = node_last_line(node)
          @chain_snapshot[:meta33_last_column] = node_last_column(node)
          dots
        end

        def describe_chain_shape
          @chain_snapshot ||= {}
          root = @chain_snapshot[:root]
          shape = :plain
          if root.nil?
            shape = :empty
          elsif chain_covers_safe_navigation? && chain_spans_multiple_lines?
            shape = :multiline_safe
          elsif chain_covers_safe_navigation?
            shape = :safe
          elsif chain_spans_multiple_lines?
